{
  "application": "data-visualization",
  "case_id": "case-ml-infrastructure-architecture-pipeline",
  "language": "en",
  "style": {
    "theme": "dark",
    "audience": "team-internal",
    "tone": "technical, detailed, systems-oriented"
  },
  "goal": [
    {
      "id": "end-to-end-pipeline-flow",
      "insight": "Show the complete ML infrastructure pipeline from data ingestion through monitoring, making the sequential flow from Data Platform → Feature Store → Training Cluster → Model Registry → Inference Service → AB Experiment Platform → Monitoring & Alerting visually prominent as a directed architecture"
    },
    {
      "id": "node-edge-encoding",
      "insight": "Encode node type via color (data-layer=blue, compute-layer=green, serving-layer=orange, observability-layer=red), node size by criticality score, edge thickness by data throughput volume, and edge style (solid for primary data flow, dashed for version-control/lineage links)"
    },
    {
      "id": "data-lineage-overlay",
      "insight": "Visually distinguish the data lineage and version control connections as a secondary overlay network that cross-cuts the primary pipeline flow, connecting the Version Control node to Feature Store, Model Registry, and Training Cluster"
    },
    {
      "id": "online-offline-branching",
      "insight": "Emphasize the branching at the Inference Service layer where the pipeline splits into online (real-time) and offline (batch) inference paths before converging at the AB Experiment Platform"
    },
    {
      "id": "feedback-loop-visibility",
      "insight": "Highlight the feedback loop from Monitoring & Alerting back to the Data Platform and Training Cluster, showing the closed-loop nature of the ML operations cycle"
    }
  ]
}

